import * as THREE from 'three';

/**
 * Painted foliage cards from fal-generated alpha atlases (generated by production: Nano Banana Pro sheets ->
 * BiRefNet alpha -> packed 1024 px cells). assets/textures/plants.webp (4x3) and trees.webp (3x2).
 * Cards are Y-axis billboards (or fixed-yaw for hanging vines), one instanced draw call per atlas,
 * alpha-to-coverage, wind sway and per-instance tint/mirroring.
 */
export type PlantKind = 'broadleaf' | 'fern' | 'flowerbush' | 'vine' | 'reeds' | 'palmlet' | 'bougainvillea' | 'elephantear' | 'hibiscus' | 'fernflower' | 'agave' | 'vinecurtain';
export type TreeKind = 'acacia' | 'roundtree' | 'palm' | 'jungletree' | 'gnarled';
export type CardKind = PlantKind | TreeKind;
export interface CardLayout { cols: number; rows: number; cells: Partial<Record<CardKind, { cell: [number, number]; fill: number }>> }
/** fill = fraction of the cell the art fills vertically (bottom-anchored; hanging vines are top-anchored) */
export const PLANT_LAYOUT: CardLayout = { cols: 4, rows: 3, cells: { broadleaf: { cell: [0, 0], fill: 0.783 }, fern: { cell: [1, 0], fill: 0.772 }, flowerbush: { cell: [2, 0], fill: 0.78 }, vine: { cell: [3, 0], fill: 0.976 }, reeds: { cell: [0, 1], fill: 0.977 }, palmlet: { cell: [1, 1], fill: 0.805 }, bougainvillea: { cell: [2, 1], fill: 0.804 }, elephantear: { cell: [3, 1], fill: 0.807 }, hibiscus: { cell: [0, 2], fill: 0.854 }, fernflower: { cell: [1, 2], fill: 0.632 }, agave: { cell: [2, 2], fill: 0.867 }, vinecurtain: { cell: [3, 2], fill: 0.977 } } };
export const TREE_LAYOUT: CardLayout = { cols: 3, rows: 2, cells: { acacia: { cell: [0, 0], fill: 0.964 }, roundtree: { cell: [1, 0], fill: 0.977 }, palm: { cell: [2, 0], fill: 0.977 }, jungletree: { cell: [0, 1], fill: 0.977 }, gnarled: { cell: [1, 1], fill: 0.977 } } };
const HANGING = new Set<CardKind>(['vine', 'vinecurtain']);

export class FoliageCardBuilder {
  constructor(private layout: CardLayout = PLANT_LAYOUT) {}
  private pos: number[] = []; private size: number[] = []; private uv: number[] = []; private yaw: number[] = []; private tint: number[] = [];
  get count() { return this.yaw.length; }
  /** height = visible plant height in metres; yaw = null for billboard */
  add(kind: CardKind, x: number, y: number, z: number, height: number, yaw: number | null = null, tint = 1, mirror = false) {
    const L = this.layout.cells[kind]!;
    const s = height / L.fill;
    const [cx, cy] = L.cell;
    const cw = 1 / this.layout.cols, ch = 1 / this.layout.rows;
    // vine hangs from its anchor: shift so the top of the art sits at y
    const by = HANGING.has(kind) ? y - s * 0.988 : y - s * 0.012;
    this.pos.push(x, by, z); this.size.push(mirror ? -s : s, s);
    this.uv.push(cx * cw, 1 - (cy + 1) * ch, cw, ch);
    this.yaw.push(yaw === null ? -99 : yaw); this.tint.push(tint);
  }
  build(tex: THREE.Texture, fog = true): THREE.Mesh {
    const base = new THREE.PlaneGeometry(1, 1);
    base.translate(0, 0.5, 0);
    const g = new THREE.InstancedBufferGeometry();
    g.index = base.index; g.attributes.position = base.attributes.position; g.attributes.uv = base.attributes.uv;
    g.setAttribute('iPos', new THREE.InstancedBufferAttribute(new Float32Array(this.pos), 3));
    g.setAttribute('iSize', new THREE.InstancedBufferAttribute(new Float32Array(this.size), 2));
    g.setAttribute('iUv', new THREE.InstancedBufferAttribute(new Float32Array(this.uv), 4));
    g.setAttribute('iYaw', new THREE.InstancedBufferAttribute(new Float32Array(this.yaw), 1));
    g.setAttribute('iTint', new THREE.InstancedBufferAttribute(new Float32Array(this.tint), 1));
    g.instanceCount = this.count;
    const uniforms = THREE.UniformsUtils.merge([THREE.UniformsLib.fog, { uMap: { value: null }, uTime: { value: 0 } }]);
    uniforms.uMap.value = tex;
    const mat = new THREE.ShaderMaterial({
      uniforms, fog, side: THREE.DoubleSide, alphaToCoverage: true, transparent: false,
      vertexShader: /* glsl */`
        attribute vec3 iPos; attribute vec2 iSize; attribute vec4 iUv; attribute float iYaw; attribute float iTint;
        uniform float uTime;
        varying vec2 vUv; varying float vTint; varying float vH;
        #include <fog_pars_vertex>
        void main(){
          vec3 right;
          if (iYaw < -50.0) {
            vec3 camRight = vec3(viewMatrix[0][0], viewMatrix[1][0], viewMatrix[2][0]);
            right = normalize(vec3(camRight.x, 0.0, camRight.z));
          } else right = vec3(cos(iYaw), 0.0, -sin(iYaw));
          float sway = sin(uTime * 1.6 + iPos.x * 0.37 + iPos.z * 0.21) * 0.035 * position.y * position.y;
          vec3 wp = iPos + right * (position.x * iSize.x + sway * iSize.x) + vec3(0.0, position.y * iSize.y, 0.0);
          vUv = iUv.xy + uv * iUv.zw;
          vTint = iTint; vH = position.y;
          vec4 mvPosition = viewMatrix * vec4(wp, 1.0);
          gl_Position = projectionMatrix * mvPosition;
          #include <fog_vertex>
        }`,
      fragmentShader: /* glsl */`
        uniform sampler2D uMap; varying vec2 vUv; varying float vTint; varying float vH;
        #include <fog_pars_fragment>
        void main(){
          vec4 c = texture2D(uMap, vUv);
          if (c.a < 0.35) discard;
          vec3 col = c.rgb * vTint * mix(0.8, 1.04, smoothstep(0.0, 0.5, vH));
          gl_FragColor = vec4(col, c.a);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
          #include <fog_fragment>
        }`,
    });
    const m = new THREE.Mesh(g, mat);
    m.frustumCulled = false;
    m.userData.uniforms = uniforms;
    return m;
  }
}
